update public.offers o set customer_name = coalesce(nullif(c.company_name,''),nullif(c.contact_name,'')), payload = jsonb_set(jsonb_set(coalesce(o.payload,'{}'::jsonb),'{customer,company_name}',coalesce(to_jsonb(c.company_name),'null'::jsonb),true),'{customer,contact_name}',coalesce(to_jsonb(c.contact_name),'null'::jsonb),true) from public.customers c where o.customer_id=c.id and o.offer_number='ANG-2026-04527' and o.customer_id='5c56a6bc-b5b4-4115-80cc-fb84c0f5285d' and o.status='draft' and o.signed_at is null and o.customer_name='Cakmak Deniz ' and c.company_name='Diljin Önen';